import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;class PublicExamplesTest{static String capture(Runnable action){PrintStream previous=System.out;ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(PrintStream out=new PrintStream(bytes,true,StandardCharsets.UTF_8)){System.setOut(out);action.run();}finally{System.setOut(previous);}return bytes.toString(StandardCharsets.UTF_8).replace("\r\n","\n");}@Test void publishedRadiusTwo(){Object c=TaskBinding.circle(2);assertEquals(4,TaskBinding.width(c));assertEquals(4,TaskBinding.height(c));assertEquals("circle",TaskBinding.name(c));assertEquals(12.566370614359172,TaskBinding.area(c),1e-9);}}
